// ── What each message tells the registry (jobs.Reporter) ─────────────────────

func (m ImageScanStartingMsg) Transition() jobs.Transition {
	return jobs.Transition{Kind: jobs.KindScan, Target: m.ImageName, State: jobs.ItemRunning, Cancel: m.Cancel}
}

func (m ImageScanFinishedMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindScan, Target: m.ImageName, State: jobs.ItemDone}
	if m.Err != nil {
		t.State = jobs.ItemFailed
		t.Detail = "scan failed — check logs"
	}
	return t
}

func (m RegistryPullStartingMsg) Transition() jobs.Transition {
	return jobs.Transition{Kind: jobs.KindPull, Target: m.ImageName, State: jobs.ItemRunning, Cancel: m.Cancel}
}

func (m RegistryPullCompleteMsg) Transition() jobs.Transition {
	t := jobs.Transition{Kind: jobs.KindPull, Target: m.ImageName, State: jobs.ItemDone}
	switch {
	case len(m.InUse) > 0:
		t.State = jobs.ItemFailed
		t.Detail = "not updated — the image is in use"
	case isBlocked(m.Err):
		// The reason, not "check logs": it names the rule, and it is what an
		// agent that asked for the pull reads (§3.82).
		t.State = jobs.ItemFailed
		t.Detail = "refused — " + m.Err.Error()
	case m.Err != nil:
		t.State = jobs.ItemFailed
		t.Detail = "pull failed — check logs"
	}
	return t
}

// Compile-time proof that every progress message can be applied. One added
// without a transition would leave its row spinning for the life of the view.
var (
	_ jobs.Reporter = ImageScanStartingMsg{}
	_ jobs.Reporter = ImageScanFinishedMsg{}
	_ jobs.Reporter = RegistryPullStartingMsg{}
	_ jobs.Reporter = RegistryPullCompleteMsg{}
)
	High     int    `json:"high"`
	Medium   int    `json:"medium"`
	Low      int    `json:"low"`
	// Sensitive is the secret verdict, and it is a pointer because it has three
	// values: absent when nobody looked, false when a stage looked and found
	// nothing, true otherwise. It is `scan.Result.SecretVerdict()` that writes
	// it.
	//
	// An image had no secrets field at all until now, so **every entry already
	// on disk decodes to nil** — which is the truth: it was written by an
	// image scan that had no secrets stage whatsoever.
	Sensitive *bool `json:"sensitive,omitempty"`
	// Misconfig is the misconfiguration verdict, on Sensitive's model and for
	// its reason: nil when no stage looked. An image has misconfigurations to
	// find — `trivy image --scanners misconfig` reads the Dockerfile
	// instructions baked into its layers — so this is not a repository-only
	// field, unlike the pipeline grade.
	Misconfig *scan.MisconfigSummary `json:"misconfig,omitempty"`
	ScannedAt time.Time              `json:"scanned_at"`
}

// imageScanCacheVersion marks a file whose entries are one flat map again.
// Version 1 is the shape that grouped them by configuration context, version 0
// the one that predates contexts — and version 0 is already this shape, which is
// why reading it has nothing to do (§3.39).
const imageScanCacheVersion = 2

// imageScanCacheFile is the on-disk shape of the image scan index.
//
// It carries no context, and that is the whole of §3.39: the key is a local
// Docker reference, and `docker image ls` answers for the machine rather than
// for a configuration. Two contexts looking at `nginx:1.25` are looking at the
// same bytes, so scoping the index made a context switch drop counts for images
// that had not moved — while the full results beside it, content-addressed by
// image name, were never scoped at all.
//
// The workspace cache stays scoped, and the asymmetry is the point: a workspace
// path is reached through `workspaces_dir`, which *is* per context, so two
// contexts holding the same path may legitimately mean different work.
type imageScanCacheFile struct {
	Version int                       `json:"version"`
	Entries map[string]ImageScanEntry `json:"entries"`
}

// ImageScanCache manages the image scan results cache file.
//
// It is not bound to a configuration context: see imageScanCacheFile.
type ImageScanCache struct {
	mu      sync.RWMutex
	path    string
